using Godot;
using System;
using System.IO;
using System.Linq;
using System.Threading.Tasks;
using HakutaiKagami.Core.Contracts;
using HakutaiKagami.Core.Messaging;
public partial class NewGameFrontEnd
{
 bool RetrySuperseded=>FlowCase=="dirretry-superseded";
 int RetryDirectiveSlot=>RetrySuperseded?2:1;
 TroopDispatch RetryDirectiveRoot()=>game!.Session.DiagnosticSnapshot().NewMilitary!.UnitDirective!.Dispatches.First(d=>d.Recipient==NewGameMilitary.UnitIds[RetryDirectiveSlot]);
 TroopReceipt RetryRootReceipt()=>game!.Session.DiagnosticSnapshot().NewMilitary!.UnitDirective!.Receipts.Single(r=>r.Id==RetryDirectiveRoot().Id);
 TroopDispatch RetryDirectiveCopy()=>game!.Session.DiagnosticSnapshot().NewMilitary!.UnitDirective!.Dispatches.Last(d=>d.Message==RetryDirectiveRoot().Message);
 TroopReceipt RetryCopyReceipt()=>game!.Session.DiagnosticSnapshot().NewMilitary!.UnitDirective!.Receipts.Single(r=>r.Id==RetryDirectiveCopy().Id);
 async Task DirectiveRetryStep(int n){await Frame();var s=game!.Session;
  if(n==0){game.SelectKnownMilitary(NewGameMilitary.UnitIds[RetryDirectiveSlot]);game.ChooseMilitary(NewMilitaryAction.RemoteRecall);game.Advance(s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Dispatches.Last().DueAt+5);var known=NewGameMilitary.SelectKnownTarget(s.DiagnosticSnapshot(),NewGameMilitary.UnitIds[RetryDirectiveSlot])!;game.ExerciseUnitDirectiveGoal(new(known.Position.X+8000,known.Position.Y));Check(!game.ButtonEnabled("unit-directive-retry"),"unfailed original cannot be resent through actual control");}
  if(n==1){game.Advance(RetryDirectiveRoot().DueAt);Check(!RetryRootReceipt().Delivered&&!game.ButtonEnabled("unit-directive-retry"),"actual remote loss does not enable retry before physical failure report");}
  if(n==2){game.Advance(RetryRootReceipt().ReplyDueAt);game.Advance(Math.Max(s.Seconds,ArmyEnd()+2));Check(NewGameMilitary.AtHome(s.DiagnosticSnapshot())&&game.ButtonEnabled("unit-directive-retry"),"physically known failure plus directly observed stable home permits fixed-point retry");}
  if(n==3){if(RetrySuperseded){game.Press("unit-directive-hold");game.Advance(s.DiagnosticSnapshot().NewMilitary!.UnitDirective!.Dispatches.Last().DueAt);game.SelectDirectiveOriginal(RetryDirectiveRoot().Id);}else game.Press("rotate");Check(game.SelectedDirectiveOriginalId==RetryDirectiveRoot().Id.Value,"actual original selector retains chosen original instead of new command");}
  if(n==4){var before=s.DiagnosticSnapshot();var root=RetryDirectiveRoot();var original=before.Messaging.Messages.Single(m=>m.Id==root.Message);game.Press("unit-directive-retry");var w=s.DiagnosticSnapshot();var copy=RetryDirectiveCopy();Check(copy.Id!=root.Id&&copy.Attempt!=root.Attempt&&copy.Message==root.Message&&copy.Recipient==root.Recipient&&copy.Destination!=root.Destination&&original==w.Messaging.Messages.Single(m=>m.Id==root.Message),"actual retry sends a new carrier attempt with immutable original body/recipient/deadline to fresh known fixed address");}
  if(n==5){game.Advance(RetryDirectiveCopy().DueAt);var w=s.DiagnosticSnapshot();var r=RetryCopyReceipt();Check(r.Delivered&&r.Applied!=RetrySuperseded,"actual selected original received and applied only if not superseded by newer hold");Check(!MessageFlow.Knows(w.Messaging,r.ReplyMessage,w.PlayerControl.Value)&&NewGameMilitary.UnitDirectiveStatus(w).Contains("返書未受領"),"retry outcome remains unknown before actual return courier");}
  if(n==6){game.Advance(RetryCopyReceipt().ReplyDueAt+1);var w=s.DiagnosticSnapshot();Check(MessageFlow.Knows(w.Messaging,RetryCopyReceipt().ReplyMessage,w.PlayerControl.Value)&&NewGameMilitary.UnitDirectiveStatus(w).Contains(RetrySuperseded?"新しい命令を維持":"受令・指示を実行"),"physical reply reveals correct original-priority result");}
  if(n==7){game.Advance(Math.Max(s.Seconds,ArmyEnd()+1));var w=s.DiagnosticSnapshot();var input=w.NewMilitary!.Requests.First(q=>q.Input.Id==RetryDirectiveRoot().Id).Input.Directive!;Check(NewGameMilitary.Position(w,RetryDirectiveSlot,s.Seconds)==(RetrySuperseded?NewGameMilitary.Home(w,RetryDirectiveSlot):input.Goal),"copy preserves new hold or finishes original move without changing other command priority");}
  game.Refresh();Check(game.RecognitionModelsMatch(),"actual retry ordinary 3D matches recognized world at"+n);game.Press("save");await WaitSave();
 }
 async Task BeginDirectiveRetryContinuation(){for(int n=1;n<=7;n++)await MilitaryStep(n);for(int n=0;n<=4;n++)await RecognitionStep(n);for(int n=0;n<8;n++){await DirectiveRetryStep(n);game!.SaveCheckpoint("dirretry"+n);await Capture("s"+n,true);}await Capture("final",true);}
 async Task RestoreDirectiveRetry(){Press("load-list");await Frame();string id=File.ReadAllText(Path.Combine(TestOutput,"campaign-instance.txt"));savedList.Select(Array.FindIndex(savedRows,row=>row.Profile.Instance==id));Press("load");await Frame();for(int n=0;n<8;n++){game!.LoadCheckpoint("dirretry"+n);await Frame();await Frame();Check(game.Pose()==File.ReadAllText(Path.Combine(TestOutput,"s"+n+"-pose.json")),"same selected original/known destination and 3D after restore"+n);Check(game.SelectedDirectiveOriginalId==RetryDirectiveRoot().Id.Value,"non-default original selection belongs to same restored generation"+n);await Capture("restored-s"+n,true);for(int k=n+1;k<8;k++)await DirectiveRetryStep(k);Check(ContractJson.CanonicalHash(game.Session.DiagnosticSnapshot())==File.ReadAllText(Path.Combine(TestOutput,"final-world.sha256")),"same immutable-original future after restore"+n);await Capture("continued-s"+n,true);GD.Print("UNIT_DIRECTIVE_RETRY_RESTORED "+n);}}
 async Task RunDirectiveRetryChecks(){if(OS.GetCmdlineUserArgs().Contains("--new-game-restore"))await RestoreDirectiveRetry();else await BeginNewMilitaryFlow();if(OS.GetCmdlineUserArgs().Contains("--unit-directive-retry-film")){game!.LoadCheckpoint("dirretry6");game.Press("auto");string dir=Path.Combine(TestOutput,"film",TestKey??"normal");Directory.CreateDirectory(dir);for(int n=0;n<180;n++){await Frame();ViewportCapture.Save(GetViewport(),Path.Combine(dir,"retry-"+n.ToString("D3")+".png"));}game.Press("pause");File.WriteAllText(Path.Combine(TestOutput,"film-manifest.json"),System.Text.Json.JsonSerializer.Serialize(new{Directory=Path.GetRelativePath(TestOutput,dir),Frames=180,Checkpoint=6,Action="physically-received-original-copy"}));}File.WriteAllText(Path.Combine(TestOutput,OS.GetCmdlineUserArgs().Contains("--new-game-restore")?"restore-checks.json":"check-checks.json"),System.Text.Json.JsonSerializer.Serialize(assertions));GD.Print("UNIT_DIRECTIVE_RETRY_PASSED "+FlowCase);}
}
